// Create a consistent abstract cover style from a user's playlist name.
// The result is derived at render time, so renaming a playlist updates its cover automatically.
function playlistCoverFromName(name){
 const title=String(name||'').toLowerCase();
 const themes=[
  {match:/safar|samandar|samudra|ocean|sea|sail|wave|beach|coast|voyage|travel|journey|mariner/,color:'blue',icon:'≈',theme:'sea'},
  {match:/love|romance|heart|favourite|favorite|beloved|valentine/,color:'rose',icon:'♥',theme:'love'},
  {match:/sad|rain|blue|lonely|alone|tears|heartbreak/,color:'blue',icon:'☁',theme:'rain'},
  {match:/night|drive|midnight|late|dark|moon|sleep/,color:'plum',icon:'☾',theme:'night'},
  {match:/chill|relax|lofi|lo-fi|calm|peace|soft|slow/,color:'violet',icon:'✧',theme:'calm'},
  {match:/focus|study|work|deep|ambient|reading/,color:'mint',icon:'◉',theme:'focus'},
  {match:/happy|party|energy|dance|summer|fun|upbeat|gym|workout/,color:'amber',icon:'✦',theme:'energy'}
 ];
 const theme=themes.find(item=>item.match.test(title));
 if(theme)return theme;
 // Stable fallback: the same name always gets the same palette and symbol.
 let hash=0;for(let i=0;i<title.length;i++)hash=(hash*31+title.charCodeAt(i))|0;
 const colors=['plum','rose','blue','amber','mint','violet'];
 const icons=['♫','✦','✧','☾','♡','◉'];
 const index=Math.abs(hash)%colors.length;
 return {color:colors[index],icon:icons[index],theme:'abstract'};
}
function PlaylistArtwork({name,className='cover-art'}){const cover=playlistCoverFromName(name);return <div className={`${className} ${cover.color} cover-theme-${cover.theme}`}><div className="cover-shape shape1"/><div className="cover-shape shape2"/>{cover.theme==='sea'&&<svg className="cover-sea-waves" viewBox="0 0 320 180" preserveAspectRatio="none" aria-hidden="true"><path d="M0 106c42-25 66-25 108 0s67 25 109 0 65-25 103 0v74H0z"/><path d="M0 130c42-25 66-25 108 0s67 25 109 0 65-25 103 0v50H0z"/><path d="M0 153c42-25 66-25 108 0s67 25 109 0 65-25 103 0v27H0z"/></svg>}<span className="cover-symbol">{cover.icon}</span><div className="cover-ring"/></div>}
