const cleanLibrarySong=song=>Object.fromEntries(Object.entries({title:song?.title||'Untitled song',artist:song?.artist||'Unknown artist',url:song?.url,youtubeVideoId:song?.youtubeVideoId,thumbnail:song?.thumbnail,duration:song?.duration,playlistId:song?.playlistId,playlistName:song?.playlistName,index:song?.index}).filter(([,value])=>value!==undefined&&value!==null));
const valuesAsArray=value=>Array.isArray(value)?value:Object.values(value||{});
function resolvePlaylistLink(value){
 try{
  const url=new URL(value.trim());const host=url.hostname.toLowerCase().replace(/^www\./,'');
  if(host==='open.spotify.com'){
   const match=url.pathname.match(/^\/playlist\/([A-Za-z0-9]+)\/?$/);if(!match)return null;
   return {provider:'Spotify',sourceUrl:url.href,embedUrl:`https://open.spotify.com/embed/playlist/${match[1]}?utm_source=generator`};
  }
  if(['youtube.com','music.youtube.com','m.youtube.com'].includes(host)){
   const list=url.searchParams.get('list');if(!list)return null;
   return {provider:host==='music.youtube.com'?'YouTube Music':'YouTube',playlistId:list,sourceUrl:url.href,embedUrl:`https://www.youtube.com/embed?listType=playlist&list=${encodeURIComponent(list)}&playsinline=1`};
  }
  if(host==='jiosaavn.com'||host.endsWith('.jiosaavn.com'))return {provider:'JioSaavn',sourceUrl:url.href,embedUrl:''};
 }catch{}
 return null;
}
async function fetchYouTubePlaylist(playlistId){
 if(!youtubeApiKey)throw new Error('Add a YouTube Data API key as VITE_YOUTUBE_API_KEY in .env, then restart Vite.');
 const tracks=[];let pageToken='';
 do{
  const params=new URLSearchParams({part:'snippet',playlistId,maxResults:'50',key:youtubeApiKey});if(pageToken)params.set('pageToken',pageToken);
  const response=await fetch(`https://www.googleapis.com/youtube/v3/playlistItems?${params}`);const data=await response.json();
  if(!response.ok)throw new Error(data.error?.message||'Could not load this YouTube playlist.');
  for(const item of data.items||[]){const videoId=item.snippet?.resourceId?.videoId;if(videoId)tracks.push({title:item.snippet.title,artist:item.snippet.videoOwnerChannelTitle||item.snippet.channelTitle||'YouTube',youtubeVideoId:videoId,thumbnail:item.snippet.thumbnails?.medium?.url||item.snippet.thumbnails?.default?.url||''})}
  pageToken=data.nextPageToken||'';
 }while(pageToken&&tracks.length<500);
 if(!tracks.length)throw new Error('This playlist has no public playable videos.');
 return tracks;
}
